import sys
import re

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Increase recursion depth if needed for long reference chains
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 10000))

    # Parse cell coordinates
    def parse_cell_name(name: str):
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return col, row

    # Tokenizer
    TOKEN_RE = re.compile(
        r'\s*(<=|>=|<>|[A-Z][1-9][0-9]*:[A-Z][1-9][0-9]*|[A-Z][1-9][0-9]*|[0-9]+|[(),+\-*/=<>])'
    )

    class Parser:
        def __init__(self, s: str):
            self.tokens = TOKEN_RE.findall(s)
            self.pos = 0

        def peek(self):
            if self.pos < len(self.tokens):
                return self.tokens[self.pos]
            return None

        def next(self):
            tok = self.peek()
            self.pos += 1
            return tok

        def expect(self, tok: str):
            t = self.next()
            if t != tok:
                raise ValueError(f"Expected {tok}, got {t}")

        def parse_formula(self):
            return self.parse_add_sub()

        def parse_add_sub(self):
            node = self.parse_mul_div()
            while self.peek() in ('+', '-'):
                op = self.next()
                right = self.parse_mul_div()
                node = ('BINOP', op, node, right)
            return node

        def parse_mul_div(self):
            node = self.parse_unary()
            while self.peek() in ('*', '/'):
                op = self.next()
                right = self.parse_unary()
                node = ('BINOP', op, node, right)
            return node

        def parse_unary(self):
            if self.peek() == '-':
                self.next()
                sub = self.parse_unary()
                return ('UNARY_MINUS', sub)
            return self.parse_atom()

        def parse_atom(self):
            tok = self.peek()
            if tok is None:
                raise ValueError("Unexpected end of formula")

            if tok == '(':
                self.next()
                expr = self.parse_formula()
                self.expect(')')
                return expr

            if tok in ('SUM', 'MIN', 'MAX', 'IF'):
                func_name = self.next()
                self.expect('(')
                if func_name == 'IF':
                    left = self.parse_formula()
                    op = self.next()
                    right = self.parse_formula()
                    self.expect(',')
                    then_branch = self.parse_formula()
                    self.expect(',')
                    else_branch = self.parse_formula()
                    self.expect(')')
                    return ('IF', op, left, right, then_branch, else_branch)
                else:
                    args = []
                    while True:
                        t = self.peek()
                        if t and ':' in t:
                            self.next()
                            c1, c2 = t.split(':')
                            args.append(('RANGE', c1, c2))
                        else:
                            args.append(('EXPR', self.parse_formula()))
                        if self.peek() == ',':
                            self.next()
                        else:
                            break
                    self.expect(')')
                    return (func_name, args)

            if tok.isdigit():
                self.next()
                return ('INT', int(tok))

            # Cell name
            self.next()
            return ('CELL', tok)

    # Pre-parse contents
    parsed_cells = {}
    for name, content in cells.items():
        s = content.strip()
        if not s.startswith('='):
            try:
                val = int(s)
                parsed_cells[name] = ('LITERAL', val)
            except ValueError:
                parsed_cells[name] = ('LITERAL', 0)
        else:
            p = Parser(s[1:])
            ast = p.parse_formula()
            parsed_cells[name] = ('FORMULA', ast)

    # State tracking:
    # 0 = unvisited, 1 = in progress, 2 = done
    state = {name: 0 for name in cells}
    values = {}

    def is_error(val):
        return isinstance(val, str)

    def eval_cell(name: str):
        if name not in cells:
            return 0
        if state[name] == 2:
            return values[name]
        if state[name] == 1:
            return "#CYCLE!"

        state[name] = 1
        item_type, data = parsed_cells[name]
        if item_type == 'LITERAL':
            res = data
        else:
            res = eval_node(data)

        values[name] = res
        state[name] = 2
        return res

    def eval_node(node):
        ntype = node[0]

        if ntype == 'INT':
            return node[1]

        if ntype == 'CELL':
            return eval_cell(node[1])

        if ntype == 'UNARY_MINUS':
            val = eval_node(node[1])
            if is_error(val):
                return val
            return -val

        if ntype == 'BINOP':
            op, left_node, right_node = node[1], node[2], node[3]
            left_val = eval_node(left_node)
            if is_error(left_val):
                return left_val
            right_val = eval_node(right_node)
            if is_error(right_val):
                return right_val

            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return "#DIV/0!"
                # Truncate toward zero for integer division
                return int(left_val / right_val)

        if ntype == 'IF':
            op, left_node, right_node, then_node, else_node = node[1], node[2], node[3], node[4], node[5]
            left_val = eval_node(left_node)
            if is_error(left_val):
                return left_val
            right_val = eval_node(right_node)
            if is_error(right_val):
                return right_val

            cond = False
            if op == '=':
                cond = (left_val == right_val)
            elif op == '<>':
                cond = (left_val != right_val)
            elif op == '<':
                cond = (left_val < right_val)
            elif op == '<=':
                cond = (left_val <= right_val)
            elif op == '>':
                cond = (left_val > right_val)
            elif op == '>=':
                cond = (left_val >= right_val)

            if cond:
                return eval_node(then_node)
            else:
                return eval_node(else_node)

        if ntype in ('SUM', 'MIN', 'MAX'):
            collected_values = []
            for arg in node[1]:
                kind = arg[0]
                if kind == 'EXPR':
                    val = eval_node(arg[1])
                    if is_error(val):
                        return val
                    collected_values.append(val)
                elif kind == 'RANGE':
                    c1, c2 = arg[1], arg[2]
                    col1, row1 = parse_cell_name(c1)
                    col2, row2 = parse_cell_name(c2)
                    min_col, max_col = min(col1, col2), max(col1, col2)
                    min_row, max_row = min(row1, row2), max(row1, row2)

                    # Row-major order: top row first, left to right within row
                    for r in range(min_row, max_row + 1):
                        for c in range(min_col, max_col + 1):
                            cell_name = f"{chr(ord('A') + c)}{r}"
                            if cell_name in cells:
                                val = eval_cell(cell_name)
                                if is_error(val):
                                    return val
                                collected_values.append(val)

            if ntype == 'SUM':
                return sum(collected_values)
            elif ntype == 'MIN':
                return min(collected_values) if collected_values else 0
            elif ntype == 'MAX':
                return max(collected_values) if collected_values else 0

        raise ValueError(f"Unknown node type: {ntype}")

    for name in cells:
        eval_cell(name)

    return {name: values[name] for name in cells}
